func:
// 模擬設備：数秒ごとに状態を変えて MQTT に出す。
// 実機では、このノードの代わりに PLC から状態を読むノード（OPC UA・MC プロトコル・Modbus など）を置き、
// 同じ形（state・alarmCode・occurredAt）で同じトピックへ出せばよい
const states = ['Running', 'Running', 'Running', 'Idle', 'Setup', 'Stopped', 'Failure'];
const alarms = { Stopped: ['A-101', 'A-102', 'Z-999'], Failure: ['E-201'] };
const state = states[Math.floor(Math.random() * states.length)];
const codes = alarms[state];
msg.topic = 'mes/equipment/' + (env.get('SIM_EQUIPMENT') || 'EQ-06') + '/state';
msg.payload = {
    state: state,
    alarmCode: codes ? codes[Math.floor(Math.random() * codes.length)] : null,
    occurredAt: new Date().toISOString()
};
node.status({ text: state });
return msg;

// トピック mes/equipment/<資産番号>/state から設備を、本文から状態を取り出して送信待ちにためる。
// eventId はここで振る（送り直しても同じ値のままなので、MES 側で重複として弾かれる）
const code = msg.topic.split('/')[2];
const p = msg.payload || {};
const seq = (flow.get('seq') || 0) + 1;
flow.set('seq', seq);
const queue = flow.get('queue') || [];
queue.push({
    equipmentCode: code,
    eventId: code + '-' + Date.now() + '-' + seq,
    occurredAt: p.occurredAt || new Date().toISOString(),
    state: p.state,
    alarmCode: p.alarmCode || null
});
// MES に届かない間もためておく。ため過ぎないよう、上限を超えたら古いものから捨てる
const limit = 10000;
flow.set('queue', queue.length > limit ? queue.slice(queue.length - limit) : queue);
node.status({ text: '送信待ち ' + Math.min(queue.length, limit) + ' 件' });
return null;

// ためたイベントをまとめて MES へ送る。前の送信の結果が返るまでは次を送らない
if (flow.get('sending')) {
    return null;
}
const queue = flow.get('queue') || [];
if (queue.length === 0) {
    return null;
}
const batch = queue.slice(0, 500);
flow.set('sending', batch.length);
msg.url = (env.get('MES_URL') || 'http://mesapp:8080') + '/api/integration/v1/equipment-events';
msg.method = 'POST';
msg.headers = { 'X-Api-Key': env.get('MES_API_KEY') || '', 'Content-Type': 'application/json' };
msg.payload = { events: batch };
return msg;

// 送った分を送信待ちから外す。送れなかったとき（MES が止まっている・キーが違う）は外さず、次の回に送り直す。
// 1件ごとの拒否（遅着・設定の誤りなど）は送り直しても通らないので、デバッグ欄に出すだけにする
const sent = flow.get('sending') || 0;
flow.set('sending', 0);
if (msg.statusCode === 400) {
    // 要求の形が壊れている（送り直しても通らない）。送信待ちから外して知らせる
    flow.set('queue', (flow.get('queue') || []).slice(sent));
    node.status({ fill: 'red', shape: 'dot', text: '要求が拒否されました（400）' });
    node.warn(msg.payload);
    return null;
}
if (msg.statusCode === undefined) {
    // MES に繋がらなかった（名前が引けない・接続を拒否された等）。HTTP ノードはエラーをここにも流す
    node.status({ fill: 'yellow', shape: 'ring', text: '繋がりません。次の回に送り直します' });
    return null;
}
if (msg.statusCode !== 200) {
    node.status({ fill: 'yellow', shape: 'ring', text: '送れませんでした（' + msg.statusCode + '）。次の回に送り直します' });
    node.warn(msg.payload);
    return null;
}
flow.set('queue', (flow.get('queue') || []).slice(sent));
const r = msg.payload;
node.status({ fill: 'green', shape: 'dot', text: '採用 ' + r.accepted + '・重複 ' + r.duplicate + '・拒否 ' + r.rejected });
const rejected = r.results.filter(x => x.result === 'Rejected');
if (rejected.length === 0) {
    return null;
}
msg.payload = rejected;
return msg;

// MES に繋がらなかった（名前が引けない・接続を拒否された等）。送信待ちは残し、次の回に送り直す
flow.set('sending', 0);
node.status({ fill: 'yellow', shape: 'ring', text: '繋がりません。次の回に送り直します' });
return null;

// MES の Webhook の署名を確かめる（Spec.md 3.8 Webhook）。
// 署名は「X-Mes-Timestamp.本文」の HMAC-SHA256。本文は JSON に読み替える前のバイト列そのもの
// （settings.js の httpNodeMiddleware が msg.payload に残している）。読み替えた後の JSON から作り直すと、
// 数値の書き方（10.0000 と 10 など）が変わって署名が合わない。
const secret = env.get('MES_WEBHOOK_SECRET') || '';
const timestamp = msg.req.headers['x-mes-timestamp'] || '';
const signature = msg.req.headers['x-mes-signature'] || '';
const body = typeof msg.payload === 'string' ? msg.payload : null;

function reject(reason) {
    node.warn('受け付けませんでした：' + reason);
    msg.statusCode = 401;
    msg.payload = { error: reason };
    return [msg, null];
}
if (!secret) return reject('MES_WEBHOOK_SECRET が設定されていません');
if (body === null) return reject('本文を生のまま受け取れていません（settings.js を確かめてください）');
// 古い要求の送り直し（再生攻撃）を弾く。MES とこの PC の時計は NTP で揃える
if (!/^\d+$/.test(timestamp) || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return reject('時刻が5分以上ずれています');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');
if (expected.length !== signature.length
    || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))) return reject('署名が合いません');

const event = JSON.parse(body);
// 少なくとも1回届くので、同じ id は2回目以降を捨てる（覚えるのは直近の1000件）
const seen = flow.get('seenIds') || [];
const duplicate = seen.includes(event.id);
if (!duplicate) {
    seen.push(event.id);
    flow.set('seenIds', seen.slice(-1000));
}
// 先に 2xx を返す（MES は応答を待っている。転送に時間がかかっても再送されないように）
const reply = { req: msg.req, res: msg.res, statusCode: 200, payload: { received: event.id } };
if (duplicate) {
    node.log('重複を捨てました：' + event.id);
    return [reply, null];
}
return [reply, { payload: event }];

// 通知をチャットの形にする。CHAT_KIND＝slack（既定）か teams。
// 送り先は CHAT_WEBHOOK_URL（Slack の Incoming Webhook、Teams のワークフローの「Webhook 要求を受信したとき」の URL）。
// 既定はこのフローの中の模擬（/chat-mock）で、実際のチャットには送らない
const event = msg.payload;
const url = env.get('CHAT_WEBHOOK_URL') || 'http://localhost:1880/chat-mock';
const text = '[' + event.type + '] ' + event.summary;
msg.url = url;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
if ((env.get('CHAT_KIND') || 'slack') === 'teams') {
    // Teams のワークフローは Adaptive Card を受ける
    msg.payload = {
        type: 'message',
        attachments: [{
            contentType: 'application/vnd.microsoft.card.adaptive',
            content: {
                $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
                type: 'AdaptiveCard',
                version: '1.4',
                body: [{ type: 'TextBlock', text: text, wrap: true }],
            },
        }],
    };
} else {
    msg.payload = { text: text };
}
return msg;
